class _ConvTranspose3dParameters(nn.Module):
    def __init__(self, in_channels, out_channels, kernel_size, stride, padding,
                 output_padding, dilation, groups, bias):
        super().__init__()
        self.in_channels = in_channels
        self.out_channels = out_channels
        self.kernel_size = _triple(kernel_size)
        self.stride = _triple(stride)
        self.padding = _triple(padding)
        self.output_padding = _triple(output_padding)
        self.dilation = _triple(dilation)
        self.groups = groups
        self.transposed = True
        self.padding_mode = "zeros"

        if groups <= 0:
            raise ValueError("groups must be a positive integer")
        if in_channels % groups != 0:
            raise ValueError("in_channels must be divisible by groups")
        if out_channels % groups != 0:
            raise ValueError("out_channels must be divisible by groups")
        if any(s <= 0 for s in self.stride):
            raise ValueError("stride must be greater than zero")
        if any(d <= 0 for d in self.dilation):
            raise ValueError("dilation must be greater than zero")
        if any(op >= max(s, d) for op, s, d in zip(self.output_padding, self.stride, self.dilation)):
            raise ValueError("output_padding must be smaller than either stride or dilation")

        self.weight = nn.Parameter(
            torch.empty((in_channels, out_channels // groups) + self.kernel_size)
        )
        if bias:
            self.bias = nn.Parameter(torch.empty(out_channels))
        else:
            self.register_parameter("bias", None)
        self.reset_parameters()

    def reset_parameters(self):
        nn.init.kaiming_uniform_(self.weight, a=math.sqrt(5))
        if self.bias is not None:
            fan_in = (self.out_channels // self.groups) * (
                self.kernel_size[0] * self.kernel_size[1] * self.kernel_size[2]
            )
            if fan_in != 0:
                bound = 1.0 / math.sqrt(fan_in)
                nn.init.uniform_(self.bias, -bound, bound)

class ModelNew(nn.Module):
    def __init__(self, in_channels: int, out_channels: int, kernel_size: int,
                 stride: int = 1, padding: int = 0, output_padding: int = 0,
                 dilation: int = 1, groups: int = 1, bias: bool = False):
        super().__init__()
        self.conv_transpose3d = _ConvTranspose3dParameters(
            in_channels, out_channels, kernel_size, stride, padding,
            output_padding, dilation, groups, bias
        )

    def forward(self, x: torch.Tensor) -> torch.Tensor:
        conv = self.conv_transpose3d
        if x.dim() != 5:
            raise RuntimeError("Expected 5D input")
        if not x.is_cuda:
            raise RuntimeError("PTX execution requires a CUDA input tensor")
        if x.dtype != torch.float32 or conv.weight.dtype != torch.float32:
            raise RuntimeError("This PTX implementation specializes in float32 tensors")
